mapper.select:
SELECT id, user_id, title, created_at, updated_at
FROM qa_conversations
WHERE id = #{id} AND user_id = #{userId}

mapper.delete:
DELETE FROM qa_conversations
WHERE id = #{id} AND user_id = #{userId}
  AND NOT EXISTS (SELECT 1 FROM qa_messages WHERE conversation_id = #{id})

mapper.select:
SELECT c.id, c.title, COUNT(m.id) AS message_count, c.created_at, MAX(m.created_at) AS last_active FROM qa_conversations c JOIN qa_messages m ON m.conversation_id = c.id WHERE c.user_id = #{userId}
AND (c.title ILIKE #{qPattern} OR EXISTS (SELECT 1 FROM qa_messages m2 WHERE m2.conversation_id = c.id AND (m2.question ILIKE #{qPattern} OR m2.answer ILIKE #{qPattern})))
GROUP BY c.id ORDER BY MAX(m.created_at) DESC LIMIT #{limit}
